GLYPHS = {c: [int(r[i:i + 2], 16) for i in range(0, len(r), 2)]
          for c, r in zip(_CHARS, _DATA.split(';'))}
FALLBACK = GLYPHS.get('?')


SPACE = 4


def _span(g):
    """(first lit column, advance) of a glyph: its own width plus one column of spacing"""
    bits = 0
    for r in g:
        bits |= r
    if not bits:
        return 0, SPACE
    lo = (bits & -bits).bit_length() - 1
    return lo, bits.bit_length() - lo + 1


SPAN = {c: _span(g) for c, g in GLYPHS.items()}


def glyph(ch):
    return GLYPHS.get(ch) or GLYPHS.get(ch.upper()) or FALLBACK


def advance(ch):
    g = glyph(ch)
    return (SPAN.get(ch) or _span(g))[1]


def width(text):
    """advance of `text` in font pixels (proportional)"""
    return sum(advance(c) for c in text)


def runs(text):
    """(x, y, w) horizontal runs of lit pixels, in font pixels, top-left of the line at 0, 0"""
    out = []
    ox = 0
    for ch in text:
        g = glyph(ch)
        lo, adv = SPAN.get(ch) or _span(g)
        for y, bits in enumerate(g):
            bits >>= lo
            x = 0
            while bits >> x:
                if bits >> x & 1:
                    k = x
                    while bits >> k & 1:
                        k += 1
                    out.append((ox + x, y, k - x))
                    x = k
                else:
                    x += 1
        ox += adv
    return out
